'use strict';

// MODULES //

var tape = require( 'tape' );
var isBigInt = require( '@stdlib/assert/is-bigint' );
var BigInt = require( '@stdlib/bigint/ctor' );
var xorshift128plus = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof xorshift128plus, 'function', 'main export is a function' );
	t.end();
});

tape( 'calling the function without arguments returns a PRNG function', function test( t ) {
	var rng = xorshift128plus();
	t.strictEqual( typeof rng, 'function', 'returns a function' );
	t.end();
});

tape( 'calling with empty options object returns a PRNG function', function test( t ) {
	var rng = xorshift128plus( {} );
	t.strictEqual( typeof rng, 'function', 'returns a function' );
	t.end();
});

tape( 'calling with a number seed returns a PRNG function', function test( t ) {
	var rng = xorshift128plus({
		'seed': 12345
	});
	t.strictEqual( typeof rng, 'function', 'returns a function' );
	t.end();
});

tape( 'calling with a BigInt seed returns a PRNG function', function test( t ) {
	var rng = xorshift128plus({
		'seed': BigInt( 12345 )
	});
	t.strictEqual( typeof rng, 'function', 'returns a function' );
	t.end();
});

tape( 'seeded generators with same seed produce identical sequences', function test( t ) {
	var rng1 = xorshift128plus({
		'seed': BigInt( 54321 )
	});
	var rng2 = xorshift128plus({
		'seed': BigInt( 54321 )
	});
	var i;

	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( rng1().toString(), rng2().toString(), 'iteration '+i+': same output' );
	}
	t.end();
});

tape( 'different seeds produce different sequences', function test( t ) {
	var different = 0;
	var rng1 = xorshift128plus({
		'seed': BigInt( 111 )
	});
	var rng2 = xorshift128plus({
		'seed': BigInt( 222 )
	});
	var i;

	for ( i = 0; i < 100; i++ ) {
		if ( rng1().toString() !== rng2().toString() ) {
			different += 1;
		}
	}
	t.strictEqual( different > 95, true, 'most values are different' );
	t.end();
});

tape( 'zero seed is converted to 1n', function test( t ) {
	var rng1 = xorshift128plus({
		'seed': BigInt( 0 )
	});
	var rng2 = xorshift128plus({
		'seed': BigInt( 1 )
	});
	var i;

	for ( i = 0; i < 50; i++ ) {
		t.strictEqual( rng1().toString(), rng2().toString(), 'iteration '+i+': same output' );
	}
	t.end();
});

tape( 'accepts number seed and converts to BigInt', function test( t ) {
	var rng1 = xorshift128plus({
		'seed': 12345
	});
	var rng2 = xorshift128plus({
		'seed': BigInt( 12345 )
	});
	var i;

	for ( i = 0; i < 50; i++ ) {
		t.strictEqual( rng1().toString(), rng2().toString(), 'iteration '+i+': same output' );
	}
	t.end();
});

tape( 'the PRNG returns BigInt values', function test( t ) {
	var rng = xorshift128plus({
		'seed': BigInt( 42 )
	});
	var v;
	var i;

	for ( i = 0; i < 100; i++ ) {
		v = rng();
		t.strictEqual( isBigInt( v ), true, 'iteration '+i+': returns BigInt' );
	}
	t.end();
});

tape( 'the PRNG returns values in [0, 2^64)', function test( t ) {
	var rng = xorshift128plus({
		'seed': BigInt( 42 )
	});
	var max = BigInt( '0xffffffffffffffff' );
	var v;
	var i;

	for ( i = 0; i < 100; i++ ) {
		v = rng();
		t.strictEqual( v >= BigInt( 0 ) && v <= max, true, 'iteration '+i+': value in valid range' );
	}
	t.end();
});

tape( 'the normalized method returns numbers in [0, 1)', function test( t ) {
	var rng = xorshift128plus({
		'seed': BigInt( 42 )
	});
	var v;
	var i;

	for ( i = 0; i < 1000; i++ ) {
		v = rng.normalized();
		t.strictEqual( typeof v, 'number', 'iteration '+i+': returns number' );
		t.strictEqual( v >= 0.0 && v < 1.0, true, 'iteration '+i+': in [0, 1)' );
	}
	t.end();
});

tape( 'normalized sequences are deterministic', function test( t ) {
	var rng1 = xorshift128plus({
		'seed': BigInt( 99999 )
	});
	var rng2 = xorshift128plus({
		'seed': BigInt( 99999 )
	});
	var i;

	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( rng1.normalized(), rng2.normalized(), 'iteration '+i+': same normalized output' );
	}
	t.end();
});

tape( 'the PRNG has a seed property', function test( t ) {
	var seed;
	var rng = xorshift128plus({
		'seed': BigInt( 12345 )
	});
	seed = rng.seed;

	t.strictEqual( isBigInt( seed ), true, 'seed is BigInt' );
	t.strictEqual( seed, BigInt( 12345 ), 'seed value is correct' );
	t.end();
});

tape( 'the PRNG has a state property', function test( t ) {
	var state;
	var rng = xorshift128plus({
		'seed': BigInt( 12345 )
	});
	state = rng.state;

	t.strictEqual( Array.isArray( state ), true, 'state is Array' );
	t.strictEqual( state.length, 6, 'state has correct length' );
	t.strictEqual( state[ 0 ], BigInt( 1 ), 'version is 1n' );
	t.strictEqual( state[ 1 ], BigInt( 2 ), 'state length is 2n' );
	t.strictEqual( isBigInt( state[ 2 ] ), true, 'state[0] is BigInt' );
	t.strictEqual( isBigInt( state[ 3 ] ), true, 'state[1] is BigInt' );
	t.strictEqual( state[ 4 ], BigInt( 1 ), 'seed length is 1n' );
	t.strictEqual( state[ 5 ], BigInt( 12345 ), 'seed is stored' );
	t.end();
});

tape( 'calling .copy() returns an independent PRNG with same state', function test( t ) {
	var rng1 = xorshift128plus({
		'seed': BigInt( 54321 )
	});
	var rng2;
	var v1;
	var v2;
	var i;

	// Generate some values to advance state
	for ( i = 0; i < 50; i++ ) {
		rng1();
	}

	// Copy the PRNG
	rng2 = rng1.copy();

	// Both should generate identical sequences from this point
	for ( i = 0; i < 100; i++ ) {
		v1 = rng1();
		v2 = rng2();
		t.strictEqual( v1.toString(), v2.toString(), 'iteration '+i+': identical output' );
	}
	t.end();
});

tape( 'setting state via .state property restores sequence', function test( t ) {
	var state;
	var rng = xorshift128plus({
		'seed': BigInt( 54321 )
	});
	var arr;
	var i;

	// Generate some values
	for ( i = 0; i < 100; i++ ) {
		rng();
	}

	// Capture state
	state = rng.state;

	// Generate more values
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( rng() );
	}

	// Restore state
	rng.state = state;

	// Verify sequence is replayed
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( rng().toString(), arr[ i ].toString(), 'iteration '+i+': restored sequence' );
	}
	t.end();
});

tape( 'copy option=true makes independent copy', function test( t ) {
	var state = [
		BigInt( 1 ),
		BigInt( 2 ),
		BigInt( 12345 ),
		BigInt( 67890 ),
		BigInt( 1 ),
		BigInt( 12345 )
	];
	var rng1 = xorshift128plus({
		'state': state,
		'copy': true
	});
	var rng2 = xorshift128plus({
		'state': state,
		'copy': true
	});
	var v1;
	var v2;

	state[ 2 ] = BigInt( 99999 ); // Modify original state array

	v1 = rng1();
	v2 = rng2();

	t.strictEqual( v1.toString(), v2.toString(), 'copies are independent of original' );
	t.end();
});

tape( 'the PRNG has a toJSON method', function test( t ) {
	var json;
	var rng = xorshift128plus({
		'seed': BigInt( 12345 )
	});
	json = rng.toJSON();

	t.strictEqual( typeof json, 'object', 'returns object' );
	t.strictEqual( json.type, 'PRNG', 'type is PRNG' );
	t.strictEqual( json.name, 'xorshift128+', 'name is correct' );
	t.strictEqual( Array.isArray( json.state ), true, 'state is array' );
	t.strictEqual( json.state.length, 6, 'state array has correct length' );
	t.end();
});

tape( 'the PRNG has a NAME property', function test( t ) {
	var rng = xorshift128plus();
	t.strictEqual( rng.NAME, 'xorshift128+', 'NAME is correct' );
	t.end();
});

tape( 'throws error if options is not an object', function test( t ) {
	var values;
	var i;

	values = [
		'string',
		123,
		true,
		null,
		undefined,
		[],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws(badValue( values[ i ] ), TypeError, 'throws TypeError for '+typeof values[ i ]);
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			xorshift128plus( value );
		};
	}
});

tape( 'throws error if seed is not a number or BigInt', function test( t ) {
	var values;
	var i;

	values = [
		'string',
		true,
		null,
		undefined,
		{},
		[]
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws(badValue( values[ i ] ), TypeError, 'throws TypeError for '+typeof values[ i ]);
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			xorshift128plus({
				'seed': value
			});
		};
	}
});

