tape( 'the PRNG has good period (state doesn\'t cycle quickly)', function test( t ) {
	var firstVal;
	var found;
	var rng;
	var i;

	rng = xorshift128plus({
		'seed': BigInt( 42 )
	});
	firstVal = rng();
	found = false;

	// Generate 10000 values and check we don't see the initial state repeated
	for ( i = 1; i < 10000; i++ ) {
		if ( rng().toString() === firstVal.toString() ) {
			found = true;
			break;
		}
	}

	t.strictEqual( found, false, 'no premature cycling detected in 10000 iterations' );
	t.end();
});

tape( 'normalized output is reasonably uniform', function test( t ) {
	var ratio;
	var high = 0;
	var rng = xorshift128plus({
		'seed': BigInt( 42 )
	});
	var low = 0;
	var v;
	var i;

	for ( i = 0; i < 10000; i++ ) {
		v = rng.normalized();
		if ( v < 0.5 ) {
			low += 1;
		} else {
			high += 1;
		}
	}

	ratio = low / high;
	t.strictEqual( ratio > 0.9 && ratio < 1.1, true, 'distribution is approximately uniform' );
	t.end();
});
